import re
OCR_CLASS={'0':'0O','1':'1IL','2':'2Z','3':'3','4':'4A','5':'5S','6':'6G','7':'7T','8':'8B','9':'9'}
def dc(d): return '['+re.escape(OCR_CLASS[d])+']'
def seq(digits,G):
    return (r'[^\n]{0,%d}?' % G).join(dc(d) for d in digits)
def build(Y,N,G=8,allow_rev=True,allow_short_year=True):
    ys=[Y]; ns=[N]
    if allow_rev: ys.append(Y[::-1]); ns.append(N[::-1])
    alts=[]
    for y in ys:
        for n in ns:
            # year (4-digit)
            alts.append(seq(y,G)+r'[^\n]{0,%d}?'%G+r'0{0,4}'+seq(n,G))
            if allow_short_year and y==Y:
                # two-digit year followed by a separator-ish gap
                alts.append(seq(Y[2:],G)+r'[^\n]{0,%d}?'%G+r'0{0,4}'+seq(n,G))
    return re.compile('|'.join('(?:%s)'%a for a in alts), re.I)
