import re, itertools
OCRTR=str.maketrans({'O':'0','Q':'0','Z':'2','I':'1','L':'1','S':'5','B':'8','G':'6','T':'7'})
def gen3(row):
    up=row.upper()
    s2=up.translate(OCRTR)
    ps=re.findall(r'\d+', s2)
    N=set(); Y=set()
    # ordered joins of up to 3 pieces (any order)
    idxs=range(len(ps))
    for k in (1,2,3):
        for combo in itertools.permutations(idxs, k):
            if k>1 and max(combo)-min(combo)>4: continue
            c=''.join(ps[i] for i in combo)
            for L in range(4,8):
                for a in range(0,len(c)-L+1):
                    sub=c[a:a+L]
                    N.add(sub.lstrip('0') or '0')
                    N.add(sub[::-1].lstrip('0') or '0')   # reversed families
            if len(c)==4 and c[:2] in ('19','20'): Y.add(int(c))
            if len(c)==4 and c[:2] not in ('19','20'): Y.add(int('20'+c[:2]))  # ? handled below
            if len(c)==4 and c[::-1][:2] in ('19','20'): Y.add(int(c[::-1]))  # reversed year
    for p in ps:
        if len(p)==2: Y.add(2000+int(p))
    for m in re.finditer(r'_(\d\d)', s2): Y.add(1970+int(m.group(1)))
    # swap family: SWAP00D + following piece
    for m in re.finditer(r'SWAP0{1,2}(\d)', s2):
        d=m.group(1)
        rest=s2[m.end():]
        for q in re.findall(r'\d+', rest)[:3]:
            for L in (4,5):
                if len(q)>=L: N.add((d+q[:L]).lstrip('0') or '0')
    # hex family
    for m in re.finditer(r'(?:HEX|MIX|EXMIX)([0-9A-F]{3,4})', up):
        try: N.add(str(int(m.group(1),16)))
        except: pass
    return N,Y
